# -*- coding: utf-8 -*-
"""
vokabeln.py  –  HIER WOHNT DER GESAMTE LERNINHALT

Das ist die einzige Datei, die du zum Erweitern der App anfassen musst.

Aufbau:
  KATEGORIEN  = Liste von Levels. DIE REIHENFOLGE IN DIESER LISTE IST DIE
                LEVEL-REIHENFOLGE: das erste ist Level 1, das zweite Level 2 usw.
                Ein Level wird erst spielbar, wenn der Test des vorherigen
                bestanden ist. Jedes Level hat
                  "id"     : kurzer Name ohne Leerzeichen/Umlaute (intern)
                  "label"  : Name, der in der App angezeigt wird
                  "sektion": id der Sektion aus SEKTIONEN ("alltag", "saetze", "amt")
                  "tipp"   : ein Satz, der in der App über dem Level steht
                  "baut_auf": Liste früherer Level-ids, deren Wörter hier
                             gebraucht werden. Der Level-Test holt daraus seine
                             Wiederholungsfragen (3 von 10 Fragen).
                  "reihenfolge": optional True (seit 26.10.2026): die neuen
                             Wörter kommen in der Reihenfolge von "words"
                             dran statt gemischt (jedan, dva ... deset, nula). Ajdin:
                             „bei der zahlen sektion am besten die zahlen in
                             reihenfolge lernen sowie wochentage und wo es
                             noch passt“. Gesetzt bei zahlen, wochentage,
                             monate und mengen (Zahlen im Satz: jedan brat,
                             dva brata, pet braće - je Hauptwort erst eins,
                             dann die Mehrzahl), den Leveln mit einer
                             eindeutigen Reihe. Seit 26.10.2026 abends auch
                             bei konjugation und zukunft (je Verb ja, ti,
                             on/ona, mi, vi, oni) und routine (aufstehen bis
                             schlafen gehen). Ajdin: „und auch reihenfolge
                             berücksichtigen wo es noch sinn ergibt geh
                             durch die app durch“. Was nicht in die Folge
                             passt, steht in der Liste danach.
                             Seit 27.10.2026 (von Ajdin auf Rückfrage zu
                             diesem Wunsch so ausgewählt) auch bei
                             vergangenheit (bio sam, bio si, bio je, bila
                             je, bili smo), modal (je Verb der Infinitiv,
                             dann ja, ti, on/ona, mi: morati, moram, moraš,
                             moramo) und adjektive (je Adjektiv groß,
                             größer, am größten: velik, veći, najveći).
                             Die Aufgaben einer Lektion, die Wiederholung, der
                             Level-Test und die Einstufung bleiben gemischt.
                  "reihe"  : optional (seit 26.10.2026): bs-Wörter dieses
                             Levels, die in einem sonst gemischten Level in
                             dieser Folge vorgestellt werden (zeit: jutro,
                             podne, večer, noć; wetter: die Jahreszeiten;
                             seit 27.10.2026 basics: die Grüße nach
                             Tageszeit, Dobro jutro, Dobar dan, Dobro veče,
                             Laku noć).
                             Der Rest bleibt gemischt; die Regel steht in
                             buildLesson() in web/index.html.
                  "words"  : Liste von Wörtern {"de": "Deutsch", "bs": "Bosnisch"}
                             Optional "auch": weitere Antworten, die beim
                             Tippen ebenfalls richtig sind, z. B. bei „groß“
                             (veliko) auch "velik". Gilt nur für dieses Wort;
                             soll es in beide Richtungen gelten, bei beiden
                             Wörtern eintragen. In der Auswahl stehen die
                             beiden nie als falsche Antwort nebeneinander.
                             Optional "partner" (seit 31.10.2026): das bs des
                             Aspekt-Gegenstücks (ostati - ostajati, doći -
                             dolaziti), wenn es in der App steht. Einmal je
                             Paar reicht, die App liest es in beide
                             Richtungen; seit Paket 2 (31.10.2026) steht es
                             bei neuen Paaren an beiden Woertern, auch am
                             alten Verb (gubiti - izgubiti, pokazivati -
                             pokazati). Die deutschen Bedeutungen duerfen
                             verschieden sein (popiti - piti, seit Paket 3
                             am 01.11.2026 izabrati „sich entscheiden /
                             wählen“ - birati „auswählen / wählen“).
                             Beide haben eigene Kennungen und
                             eigenen Lernstand (Ajdin). In der Auswahl stehen
                             sie nie zusammen; tippt man das Gegenstück,
                             kommt „Fast richtig!“ mit dem Hinweis auf das
                             andere Verb des Paares (task.partner), ohne
                             Leben. Vollendet/unvollendet zeigt die App nicht.
  SAETZE      = Lückentexte. "___" ist die Lücke, "answer" das fehlende Wort,
                "de" die deutsche Übersetzung, "kat" die Kategorie-id.
                Optional "auch": weitere Antworten, die in der Lücke ebenso
                richtig sind (seit 23.10.2026, bei „Moj ___ je pčelar.“ stric
                und die Koseformen). Gesprochen wird nur der Satz mit "answer".
  SATZBAU     = ganze Sätze zum Bauen aus Wort-Kacheln (seit 13.10.2026).
                  "kat"   : Level-id, in dem der Satz zum ersten Mal kommt
                  "bs"    : der Satz, z. B. "Dobar dan, kako ste?". Die
                            Kacheln sind seine Wörter, an Leerzeichen
                            getrennt, Satzzeichen am Rand fallen weg.
                            2 bis 8 Kacheln, kein "..." und kein " / ".
                  "de"    : was er heißt (wird übersetzt, bs nie)
                  "auch"  : optional, weitere richtige Reihenfolgen. Jede
                            muss sich aus den Kacheln von bs bauen lassen
                            (z. B. ohne das Pronomen) und darf nicht bs sein.
                  "ohne"  : optional, Wörter (klein), die bei diesem Satz nie
                            als falsche Kachel kommen dürfen, weil sie ihn
                            ebenfalls richtig machen: "somun" neben "Uzet ću
                            pogaču.", "ćao" neben "Merhaba, kako si?". Je ein
                            einzelnes Wort, keins aus dem Satz selbst.
                  "formen": optional, gebeugte Kachel -> Grundform, die bis
                            zu diesem Level im Wortschatz steht, z. B.
                            {"kahvu": "kahva"}. Nur für die Prüfung.
                  "quelle": optional, "saetze", "vokabel" oder "neu" -
                            woher der Satz stammt. Nur für uns.
                  "notiz" : optional, Anmerkung. Nur für uns.
                Jedes Wort muss bis zum Level "kat" schon gelernt sein,
                sonst schlägt tests/test_inhalt_tiefe.py an. Die App zeigt
                einen Satz erst, wenn seine Wörter dran waren.
  "zahl"      = optional an SAETZE und SATZBAU (seit 25.10.2026): die Zahl
                im Satz wechselt. Ajdin: „die sätze immer mit der gleichen
                zahl ist und nicht mal variiert“. Welche Sätze und Zahlen,
                hat er in einer Tabelle freigegeben („Ja, alle so“).
                  "wort"    : das Zahlwort, wie es heute im Satz steht
                              ("pet", "dvije"); genau einmal im Satz
                  "werte"   : die Zahlen, die vorkommen dürfen, samt der
                              heutigen. Jede braucht eine Aufnahme.
                  "de"      : die Bedeutung mit {n} für die Ziffer
                              („Jetzt ist es {n} Uhr.“), wird übersetzt;
                              Türkisch nimmt bei der Uhrzeit {lok} (7'de)
                  "weiblich": optional, 2 heißt dann dvije (kahve, sestre)
                  "frei"    : optional, "uhrzeit" (u pet, ohne Nomen) oder
                              "dana" (dva dana wie pet dana) - dann dürfen
                              2-4 und ab 5 gemischt sein, sonst nicht.
                Die App nimmt eine andere Zahl nur, wenn es den fertigen
                Satz als Aufnahme gibt und ihr Zahlwort schon gelernt ist -
                oder der Level zahlen schon hinter dem Lernenden liegt
                (bestanden oder per Einstufung übersprungen).
                Geprüft in inhalt.pruefe_zahlen().

Neues Wort:      eine Zeile im passenden "words"-Block ergänzen.
Neues Level:     einen ganzen Block nach demselben Muster kopieren und an der
                 Stelle einfügen, wo es in der Reihenfolge hingehört.
                 Der Knopf oben in der App erscheint dann automatisch.
Level-Test:      10 Fragen: 7 aus dem Level, 3 Wiederholung aus "baut_auf".
                 Ab 8 richtigen ist das Level bestanden, das nächste geht auf.
                 Zum Ausprobieren ohne Sperre: App mit  ?alle=1  öffnen,
                 also z. B.  http://localhost:8000/?alle=1
Speichern, im Browser neu laden (F5) – fertig. Der Server muss nicht neu
gestartet werden, er liest diese Datei bei jedem Aufruf frisch ein.

HINWEIS: Claude ist kein Muttersprachler. Bitte alles mit deiner Frau
durchgehen und korrigieren – besonders regionale Formen
(kahva/kafa, babo/otac, nana/baka, amidža/daidža, hiljada/tisuća).
"""

