    # ---- Sektion 11 · Wie etwas ist: Wortschatz-Paket 2 (31.10.2026) ----
    # 78 Adjektive, 9 Hauptwoerter, 6 Verben der Sinne, 1 Adverb und 1 Ausruf aus
    # Release\Wortschatz\paket_02.json, von Ajdin am 31.10.2026
    # durchgesehen. Aus Nr. 139 sind zwei Woerter geworden: okus (Essen) und
    # ukus (Stil), jedes mit eigenem Satz (Ajdins Wahl).
    # - Adjektive: "bs" ist die maennliche Form, die weibliche und die
    #   saechliche stehen in "auch" und zaehlen beim Tippen (dug: duga, dugo).
    #   Die App kennt bisher zwei Schreibweisen, "groß (m/w)" mit "velik /
    #   velika" und "schön" mit lijepo und "auch". "(m/w)" haette die
    #   deutsche Bedeutung und damit die Kennung veraendert; Ajdin hat sie
    #   ohne freigegeben. Weitere Formen nach Ajdin: mek und meko bei mekan,
    #   kompliciran bei komplikovan, sramežljiv bei stidljiv.
    # - Gleiche Schreibung: dug (lang) neben dug (Schulden, bank) und duga
    #   (Regenbogen, wetter). Saechliche Formen, die schon eigene Woerter
    #   sind: jako (sehr), pravo (geradeaus), teško (schwierig); puno steckt
    #   in Hvala puno, gotovo heisst auch fast. Weil diese Formen in "auch"
    #   stehen, kommen die beiden Woerter nie zusammen in eine Auswahl
    #   (geschwister() in web/index.html); dasselbe bs (dug, dug) schliesst
    #   distractors() ohnehin aus.
